<?php require __DIR__.'/../app/bootstrap.php'; if((int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0){http_response_code(403);exit('An admin account already exists. Remove this setup file after installation.');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';if(!$name||!$email||strlen($pass)<12){$error='Enter a name, valid email and password with at least 12 characters.';}else{$s=db()->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);header('Location: '.url('admin/login.php?created=1'));exit;}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Admin</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-login"><form method="post" class="login-card"><h1>Create First Admin</h1><p>Run this once after importing the database, then delete admin/setup.php from hosting.</p><?php if($error): ?><p class="form-error"><?=e($error)?></p><?php endif; ?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (minimum 12 characters)<input type="password" name="password" minlength="12" required></label><button class="btn btn-primary">Create Admin</button></form></body></html>
